// Draft: the specification is not approved: there is no records/approvals/1.0.0.yaml beside the specification; this file is not the approved output.
// The confirmation an action asks for before it runs, in a dialog, with the
// reason it requires typed in a text area; it is not confirmed while the
// reason is empty. runAction runs the action once confirmed.

import { api } from "../api.js";
import { refusalOf } from "./rules.js";
import { say } from "./texts.js";
import { html, onMounted, ref } from "./vue.js";

/**
 * Runs an action on a record through api.call: its path's parameters each
 * from a field of the record, and the reason, when it asks for one, as the
 * property of the body it names; an action whose operation streams a
 * download saves the file it answers. It answers undefined on a success,
 * or the message of the refusal.
 */
export async function runAction(action, record, reason, texts) {
  const path = api.pathOf(action.operation);
  const parameters = Object.fromEntries(Array.from(path.matchAll(/\{([^}]+)\}/g), ([, name]) => [name, String(record[action.parameters[name] ?? name] ?? "")]));
  try {
    const response = await api.call(action.operation, { parameters, body: action.reason ? { [action.reason.property]: reason.trim() } : undefined });
    if (response.ok) {
      if (api.streamOf(action.operation) === "download") {
        await api.save(response, action.operation);
      }
      return undefined;
    }
    return say(texts, refusalOf(action.failed, response.status)?.message ?? "screens.failed");
  } catch {
    return say(texts, "screens.failed");
  }
}

export const Confirm = {
  name: "Confirm",
  props: {
    action: { type: Object, required: true },
    texts: { type: Object, required: true },
    reason: { type: String, required: true },
    running: { type: Boolean, required: true },
  },
  emits: ["reason", "confirm", "close"],
  setup(props, { emit }) {
    const dialog = ref(null);
    onMounted(() => {
      if (dialog.value && typeof dialog.value.showModal === "function" && !dialog.value.open) {
        dialog.value.showModal();
      }
    });
    return () => {
      const { action, texts, reason, running } = props;
      const missing = action.reason !== undefined && reason.trim() === "";
      return html`<dialog
        ref=${dialog}
        class="screens-confirm"
        aria-labelledby="screens-confirm-title"
        onCancel=${(event) => {
          event.preventDefault();
          emit("close");
        }}
      >
        <h2 id="screens-confirm-title">${say(texts, action.confirm)}</h2>
        ${action.reason !== undefined
          ? html`<div class="screens-field">
              <label for="screens-reason">${say(texts, action.reason.label)}</label>
              <textarea id="screens-reason" value=${reason} maxlength=${action.reason.maxLength} aria-required="true" aria-describedby="screens-reason-hint" onInput=${(event) => emit("reason", event.target.value)}></textarea>
              <p id="screens-reason-hint" class="screens-hint">${say(texts, "screens.reason")}</p>
            </div>`
          : null}
        <div class="screens-buttons">
          <button type="button" class="screens-secondary" onClick=${() => emit("close")}>${say(texts, "screens.cancel")}</button>
          <button type="button" class="screens-danger" disabled=${running || missing} onClick=${() => emit("confirm")}>${say(texts, action.label)}</button>
        </div>
      </dialog>`;
    };
  },
};
